#include<bits/stdc++.h>

using namespace std;

int main(){
  int n,x;
  cin >> n >> x;
  vector<int> a(n-1);
  for(auto &nx : a){cin >> nx;}

  int l=0,r=100;
  while(l<=r){
    int te=(l+r)/2;
    vector<int> b=a;
    b.push_back(te);
    int sum=0,ma=0,mi=100;
    for(auto &nx : b){
      sum+=nx;
      ma=max(ma,nx);
      mi=min(mi,nx);
    }
    int score=sum-ma-mi;
    if(score>=x){r=te-1;}
    else{l=te+1;}
  }
  if(l>100){l=-1;}
  cout << l << "\n";
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

int main(){
  int n,x;
  cin >> n >> x;
  int l=100,r=0,s=0;
  for(int i=0;i<n-1;i++){
    int a;
    cin >> a;
    l=min(l,a);
    r=max(r,a);
    s+=a;
  }

  if(s-r >= x){cout << "0\n";return 0;}
  int need=x-(s-l-r);
  if(need <= r){cout << need << "\n";return 0;}
  cout << "-1\n";
  return 0;
}
